    prefix_len = 0
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] == s_out[i]:
            prefix_len += 1
        else:
            break

    # Find longest common suffix
    suffix_len = 0
    for i in range(1, min(len(s_in), len(s_out)) + 1):
        if s_in[-i] == s_out[-i]:
            suffix_len += 1
        else:
            break

    # Extract the minimal substring that needs to change
    if prefix_len + suffix_len >= min(len(s_in), len(s_out)):
        # One string is a prefix/suffix of the other
        if len(s_in) <= len(s_out):
            old_sub = s_in[prefix_len:]
            new_sub = s_out[prefix_len:]
            pos = prefix_len
        else:
            old_sub = s_in[prefix_len:len(s_in)-suffix_len]
            new_sub = s_out[prefix_len:len(s_out)-suffix_len]
            pos = prefix_len
    else:
        # Normal case
        old_sub = s_in[prefix_len:len(s_in)-suffix_len]
        new_sub = s_out[prefix_len:len(s_out)-suffix_len]
        pos = prefix_len

    return old_sub, new_sub, pos

